                      <DeleteOutlineRounded />
                    </IconButton>
                  </Tooltip>
                </TableCell>
	}
	return headers
}

// importHeaderRow finds the row that carries both required columns. Sheets
// exported from a shared template often start with a title or a blank line, so
// the first row is not always the header. When no row within the scan limit
// qualifies the first row is returned so the caller reports which column is
// missing from it.
func importHeaderRow(rows [][]string) (int, map[string]int) {
	for index, row := range rows {
		if index >= importHeaderScanLimit {
			break
		}
		headers := importHeaders(row)
		if _, hasName := headers["name"]; !hasName {
			continue
		}
		if _, hasPhone := headers["phone"]; !hasPhone {
			continue
		}
		return index, headers
	}
	return 0, importHeaders(rows[0])
}

// importConsent reads the consent column the way people fill it in: an English
// yes, a Korean 예/동의, or the O/V/✓ marks Excel users put in a check column.
func importConsent(value string) bool {
	value = strings.ToLower(strings.TrimSpace(value))
	value = strings.TrimRight(value, ".!。")
	switch value {
	case "y", "yes", "true", "t", "1", "o", "ok", "v", "✓", "✔", "☑", "○", "◯", "ㅇ",
		"동의", "동의함", "동의합니다", "동의완료", "예", "네", "확인", "완료", "체크", "있음", "함", "수집동의", "개인정보동의":
		return true
	}
	return false
}

// importScientific matches the scientific notation Excel gives a numeric cell
// under a "0.00E+00" style format: a mantissa with an optional fraction and an
// exponent.
var importScientific = regexp.MustCompile(`^(\d+)(?:\.(\d+))?[eE]([+-]?\d+)$`)

// importPhone repairs a phone cell that Excel stored as a number. A number cell
// loses its leading 0 (01012345678 becomes 1012345678, which passes the length
// check and would be saved as a wrong number), and a scientific format renders
// it as 1.012345678E+09. Only 8–10 digit values without a leading 0 are
// prefixed, so an international number (821012345678) or a short extension is
// left alone; a value that already looks like a phone number is returned byte
// for byte. Scientific notation is expanded only when the mantissa carries every
// digit of the integer — a truncated 1.01E+09 would otherwise be saved as
// 01010000000, so it is left as is for the caller to warn about unresolved
// scientific notation.
func importPhone(value string) string {
	if match := importScientific.FindStringSubmatch(value); match != nil {
		parsed, err := strconv.ParseFloat(value, 64)
		if err != nil || parsed <= 0 || parsed >= 1e15 || parsed != math.Trunc(parsed) {
			return value
		}
		integer := strconv.FormatInt(int64(parsed), 10)
		mantissa := strings.TrimLeft(match[1]+match[2], "0")
		if len(mantissa) < len(integer) {
			return value
		}
		value = integer

func visitBody(siteID string, extra map[string]any) map[string]any {
	body := map[string]any{
		"siteId":  siteID,
		"startAt": time.Now().Add(30 * time.Minute).UTC().Format(time.RFC3339),
		"endAt":   time.Now().Add(2 * time.Hour).UTC().Format(time.RFC3339),
		"purpose": "통합 테스트 방문",
		"visitors": []map[string]any{
			{"name": "김방문", "phone": "010-1234-5678", "company": "테스트상사", "consent": true},
		},
	}
	for key, value := range extra {
		body[key] = value
	}
	return body
}

func passTokenFrom(t *testing.T, created map[string]any) string {

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (url.pathname === ROSTER_PATH) {
    event.respondWith(cacheRoster(request));
    return;
  }
  // Never cache passes, QR images or any other visitor data.
  if (url.pathname.startsWith("/api/") || url.pathname.startsWith("/img/") || url.pathname === "/metrics") return;

  if (request.mode === "navigate") {
    // Pass, self-registration and kiosk enrolment URLs carry tokens; keep them
    // out of Cache Storage. The staff shell is what must open offline.
    const tokenBearing = url.search !== "" || url.pathname.startsWith("/q/") || url.pathname.startsWith("/r/") || url.pathname.startsWith("/kiosk") || url.pathname.startsWith("/reset-password/");
    if (!tokenBearing) event.respondWith(shellFirstNetwork(request));
    return;
  }
  if (url.pathname.startsWith("/assets/") || url.pathname === "/manifest.webmanifest" || url.pathname.endsWith(".svg") || url.pathname.endsWith(".png")) {
    event.respondWith(shellFirstNetwork(request));
  }
});
